314.         let word: int = bit_index / (u8::BITS as int);
315.         let bit: int = bit_index % (u8::BITS as int);
316.         if 0 <= bit_index && word < bytes.len() {
317.             (bytes[word] & (1u8 << bit)) != 0
318.         } else {
