// Copyright(c) The Maintainers of Nanvix.
// Licensed under the MIT License.

// Vmem - Specifications
//
// This file specifies the semantic contract of each Vmem method from the
// caller's perspective. The specs express what callers can rely on after
// calling map/unmap/uctrl/clone/copy/memset, NOT how the implementation
// achieves it.

verus! {

use super::{MappingEntry, VmemView, AccessPerm, is_user_addr_spec, frame_owned_by};

//==================================================================================================
// External Type Specifications
//==================================================================================================

#[verifier::external_type_specification]
#[verifier::external_body]
pub struct ExAccessPermission(crate::hal::mem::AccessPermission);

//==================================================================================================
// Vmem — View and Invariant
//==================================================================================================

/// Uninterpreted function mapping concrete Vmem state to abstract VmemView.
pub uninterp spec fn vmem_view(vmem: Vmem) -> VmemView;

impl View for Vmem {
    type V = VmemView;

    closed spec fn view(&self) -> VmemView {
        vmem_view(*self)
    }
}

impl Vmem {
    /// Top-level invariant: the abstract view is well-formed and internal
    /// concrete state is consistent with the abstraction.
    pub open spec fn inv(&self) -> bool {
        &&& self@.wf()
        &&& self.internal_inv()
    }

    /// Internal invariant relating concrete page directory / page table state
    /// to the abstract VmemView. Uninterpreted — refined when proving
    /// implementation correctness.
    pub uninterp spec fn internal_inv(&self) -> bool;
}

//==================================================================================================
// Uninterpreted spec fn for AccessPermission -> AccessPerm conversion
//==================================================================================================

/// Maps the concrete AccessPermission enum to the ghost AccessPerm struct.
pub uninterp spec fn access_perm_view(ap: AccessPermission) -> AccessPerm;

//==================================================================================================
// Vmem::map — Map a user frame into the address space
//==================================================================================================
//
// Caller contract (alloc_upages):
//   Pre:  - vaddr is in user space and page-aligned
//         - vaddr is not already mapped
//         - uframe is a valid allocated frame
//         - vmem.inv()
//   Post: - vaddr is now mapped to uframe's physical address with given permissions
//         - all other mappings are unchanged
//         - the physical frame is now owned by this vmem (uframe.leak() was called)
//         - vmem.inv() is preserved
//
// We express this via assume_specification on the map method.

//==================================================================================================
// Vmem::unmap — Unmap a user page
//==================================================================================================
//
// Caller contract (try_unmap_upage):
//   Pre:  - vaddr is in user space
//         - vmem.inv()
//   Post: - If the page was mapped: it is removed, the UserFrame is returned (ownership back)
//         - If the page was not mapped: Ok(None), no state change
//         - All other mappings are unchanged
//         - vmem.inv() is preserved

//==================================================================================================
// Vmem::uctrl — Change access permissions on a user page
//==================================================================================================
//
// Caller contract (ctrl_upage):
//   Pre:  - vaddr is in user space and mapped
//         - vmem.inv()
//   Post: - The permission of the mapping at vaddr is updated
//         - VA and PA are unchanged
//         - All other mappings are unchanged
//         - vmem.inv() is preserved

//==================================================================================================
// Vmem::clone — Create a new address space sharing kernel mappings
//==================================================================================================
//
// Caller contract (new_vmem):
//   Pre:  - source vmem.inv()
//   Post: - new vmem.inv()
//         - new vmem has the same kernel mappings as source
//         - new vmem has NO user mappings
//         - source vmem is unchanged

//==================================================================================================
// Vmem::is_user_page_mapped — Check if a user VA is mapped
//==================================================================================================
//
// Caller contract:
//   Pre:  - vaddr is in user space
//   Post: - returns true iff self@.is_mapped(vaddr@)

//==================================================================================================
// Vmem::is_user_addr — Check if a VA is in user space
//==================================================================================================
//
// Caller contract:
//   Post: - returns true iff is_user_addr_spec(va@)

//==================================================================================================
// Vmem::load — Load this address space into the CPU (write CR3)
//==================================================================================================
//
// Caller contract:
//   Pre:  - self.inv()
//   Post: - The CPU's address translation is now governed by self@
//         - This is an effectful operation (modifies hardware state)

//==================================================================================================
// Vmem::memset — Fill a mapped user page with a byte value
//==================================================================================================
//
// Caller contract (alloc_upages with clear=true):
//   Pre:  - vaddr is mapped in user space
//         - self.inv()
//   Post: - All PAGE_SIZE bytes at vaddr's physical frame are set to `value`
//         - Mappings unchanged, only memory content changes
//         - self.inv() preserved

//==================================================================================================
// Vmem::copy_from_user_unaligned — Copy bytes from user space to kernel space
//==================================================================================================
//
// Caller contract:
//   Pre:  - src range [src, src+size) is entirely in user space and fully mapped
//         - dst range [dst, dst+size) is entirely in kernel space
//         - size > 0
//   Post: - The bytes at [dst, dst+size) in kernel memory equal the bytes that
//           were at [src, src+size) via user-space address translation
//         - User-space mappings and memory are unchanged

//==================================================================================================
// Vmem::copy_to_user_unaligned — Copy bytes from kernel space to user space
//==================================================================================================
//
// Caller contract:
//   Pre:  - dst range [dst, dst+size) is entirely in user space and fully mapped
//         - src range [src, src+size) is entirely in kernel space
//         - size > 0
//   Post: - The bytes at [dst, dst+size) via user-space address translation
//           equal the bytes that were at [src, src+size) in kernel memory
//         - User-space mappings are unchanged (only memory content changes)

//==================================================================================================
// Vmem::copy_user_to_user — Copy between two user address spaces
//==================================================================================================
//
// Caller contract:
//   Pre:  - src range in src_vmem is fully mapped in user space
//         - dst range in dst_vmem is fully mapped in user space
//         - size > 0
//   Post: - Bytes at dst in dst_vmem equal bytes at src in src_vmem (pre-copy)
//         - src_vmem is unchanged
//         - dst_vmem mappings unchanged, only memory content changes

//==================================================================================================
// Vmem::map_kpage — Map a kernel page into the address space
//==================================================================================================
//
// Caller contract:
//   Pre:  - vaddr is in kernel space
//         - kpage is a valid allocated kernel frame
//         - self.inv()
//   Post: - vaddr is now mapped to kpage's physical address
//         - All other mappings are unchanged
//         - self.inv() is preserved

//==================================================================================================
// Vmem::kctrl — Change access permissions on a kernel page (or create identity map)
//==================================================================================================
//
// Caller contract (MMIO setup):
//   Pre:  - vaddr is in kernel space
//         - self.inv()
//   Post: - If dry_run: no state change, only validation
//         - If not dry_run: the page at vaddr has updated permissions
//         - self.inv() is preserved

} // end verus!

