verus! {

use super::UpoolView;
use crate::hal::mem::spec_page_size;

// ---------------------------------------------------------------------------
// External type specifications (arch crate)
// ---------------------------------------------------------------------------

#[verifier::external_type_specification]
#[verifier::external_body]
pub struct ExFrameNumber(arch::mem::paging::FrameNumber);

pub uninterp spec fn spec_frame_number_value(frame_number: arch::mem::paging::FrameNumber) -> int;

// ---------------------------------------------------------------------------
// Assumed specs for arch crate functions
// ---------------------------------------------------------------------------

pub assume_specification[ ::arch::mem::FRAME_SIZE ] -> (result: usize)
    ensures
        result == spec_page_size(),
        result > 0,
        result >= 2,
;

pub assume_specification[ arch::mem::paging::FrameNumber::from_raw_value ](value: usize) -> (result: Option<arch::mem::paging::FrameNumber>)
    ensures
        value as int * spec_page_size() <= usize::MAX as int ==> result matches Some(_),
        result matches Some(frame_number) ==> spec_frame_number_value(frame_number) == value as int,
;

pub assume_specification[ arch::mem::paging::FrameNumber::into_raw_value ](frame_number: arch::mem::paging::FrameNumber) -> (result: usize)
    ensures
        result as int == spec_frame_number_value(frame_number),
;

pub assume_specification[ FrameAddress::from_frame_number ](frame_number: arch::mem::paging::FrameNumber) -> (result: Result<FrameAddress, Error>)
    requires
        spec_frame_number_value(frame_number) * spec_page_size() <= usize::MAX as int,
