11. verus! {
12. 
13. //==================================================================================================
14. // External (opaque) dependency types
15. //
16. // These types live in lower-level, not-yet-verified crates (`sys`, `hal`,
17. // `mm::phys`). They are declared `external_body` so Verus treats them as opaque;
18. // the trust obligation is tracked here and is discharged when those modules are
19. // verified. Their projection into the abstract domain (below) is therefore
20. // `uninterp` — a mechanical consequence of the type being `external_body`.
21. //==================================================================================================
22. 
23. #[verifier::external_type_specification]
24. #[verifier::external_body]
25. pub struct ExVirtualAddress(VirtualAddress);
26. 
27. #[verifier::reject_recursive_types(T)]
28. #[verifier::external_type_specification]
29. #[verifier::external_body]
30. pub struct ExPageAligned<T: Address>(PageAligned<T>);
31. 
32. #[verifier::external_type_specification]
33. #[verifier::external_body]
34. pub struct ExAccessPermission(AccessPermission);
35. 
36. //==================================================================================================
37. // Abstract projections of the opaque address / permission types
38. //==================================================================================================
39. 
40. /// Projection of an address-like value to its raw byte address as a `nat`.
41. pub trait AddrNat {
42.     spec fn addr_nat(&self) -> nat;
43. }
44. 
45. impl AddrNat for VirtualAddress {
46.     uninterp spec fn addr_nat(&self) -> nat;
47. }
48. 
49. impl AddrNat for PageAligned<VirtualAddress> {
50.     uninterp spec fn addr_nat(&self) -> nat;
51. }
52. 
53. /// Projection of the concrete permission encoding to the abstract triple.
54. pub trait PermView {
55.     spec fn perms_view(&self) -> PagePerms;
56. }
57. 
58. impl PermView for AccessPermission {
59.     uninterp spec fn perms_view(&self) -> PagePerms;
60. }
61. 
62. //==================================================================================================
63. // Architectural constants (mirror `sys::config` / `arch::mem` layout values)
64. //==================================================================================================
65. 
66. /// Page size in bytes (`arch::mem::PAGE_SIZE`).
67. pub open spec fn page_size() -> nat {
68.     4096
69. }
70. 
71. /// First user-space byte address (`config::memory_layout::USER_BASE_RAW`).
72. pub open spec fn user_base() -> nat {
73.     0x4000_0000
74. }
75. 
76. /// One-past-last user-space byte address (`config::memory_layout::USER_END_RAW`).
77. pub open spec fn user_end() -> nat {
78.     0xf000_0000
79. }
80. 
81. /// Size of valid guest physical memory (`config::kernel::MEMORY_SIZE`).
82. pub open spec fn phys_mem_size() -> nat {
83.     ::config::kernel::MEMORY_SIZE as nat
84. }
85. 
86. //==================================================================================================
87. // Address-partition helpers (pure, total, instance-independent)
88. //==================================================================================================
89. 
90. pub open spec fn is_page_aligned(a: nat) -> bool {
91.     a % page_size() == 0
92. }
93. 
94. /// Page-aligned base of the page containing `a`.
95. pub open spec fn page_base(a: nat) -> nat {
96.     (a - (a % page_size())) as nat
97. }
98. 
99. /// Intra-page offset of `a`.
100. pub open spec fn page_offset(a: nat) -> nat {
101.     a % page_size()
102. }
103. 
104. /// Whether `a` lies in user space.
105. pub open spec fn spec_is_user_addr(a: nat) -> bool {
106.     user_base() <= a < user_end()
107. }
108. 
109. /// Whether `a` lies in kernel space (the total complement of user space).
110. pub open spec fn spec_is_kernel_addr(a: nat) -> bool {
111.     !spec_is_user_addr(a)
112. }
113. 
114. /// Whether `[start, start+size)` lies entirely in user space.
115. pub open spec fn spec_is_user_region(start: nat, size: nat) -> bool {
116.     &&& size > 0
117.     &&& user_base() <= start
118.     &&& start + size <= user_end()
119. }
120. 
121. /// Whether `[start, start+size)` lies entirely in kernel space (below the user
122. /// window). Matches the kernel half of the address partition.
123. pub open spec fn spec_is_kernel_region(start: nat, size: nat) -> bool {
124.     &&& size > 0
125.     &&& start + size <= user_base()
126. }
127. 
128. /// Whether `[start, start+size)` lies entirely within valid physical memory.
129. /// (`hal::platform::is_valid_physical_region`: rejects empty ranges.)
130. pub open spec fn spec_is_physical_region(start: nat, size: nat) -> bool {
131.     &&& size > 0
132.     &&& start + size <= phys_mem_size()
133. }
134. 
135. //==================================================================================================
136. // PagePerms — abstract access permissions
137. //==================================================================================================
138. 
139. /// Abstract access permissions of a mapped page.
140. pub struct PagePerms {
141.     pub read: bool,
142.     pub write: bool,
143.     pub execute: bool,
144. }
145. 
146. //==================================================================================================
147. // UserPageView / KernelPageView — single-mapping abstractions
148. //==================================================================================================
149. 
150. /// Abstract state of a single user-space mapping.
151. pub struct UserPageView {
152.     /// Physical base address of the backing user frame.
153.     pub frame: nat,
154.     /// Access permissions currently in effect for the page.
155.     pub perms: PagePerms,
156.     /// Whether the page is marked copy-on-write.
157.     pub cow: bool,
158. }
159. 
160. /// Abstract state of a single kernel-space mapping.
161. pub struct KernelPageView {
162.     /// Physical base address of the backing kernel page/frame.
163.     pub frame: nat,
164.     /// Access permissions currently in effect for the page.
165.     pub perms: PagePerms,
166. }
167. 
168. //==================================================================================================
169. // VmemView — abstract state of an entire address space
170. //==================================================================================================
171. 
172. /// Abstract view of a virtual memory space.
173. pub struct VmemView {
174.     /// User half: page-aligned user vaddr -> mapping.
175.     pub user: Map<nat, UserPageView>,
176.     /// Kernel half: page-aligned kernel vaddr -> mapping.
177.     pub kernel: Map<nat, KernelPageView>,
178.     /// Physical base address of the page directory (the value loaded into CR3).
179.     pub pgdir: nat,
180. }
181. 
182. impl VmemView {
183.     //==============================================================================================
184.     // Well-formedness invariant
185.     //==============================================================================================
186. 
187.     pub open spec fn inv(self) -> bool {
188.         // User keys are page-aligned user addresses.
189.         &&& forall|v: nat| #[trigger] self.user.contains_key(v)
190.                 ==> spec_is_user_addr(v) && is_page_aligned(v)
191.         // Kernel keys are page-aligned kernel addresses.
192.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v)
193.                 ==> spec_is_kernel_addr(v) && is_page_aligned(v)
194.         // User frames are valid, page-aligned, and CoW implies read-only.
195.         &&& forall|v: nat| #[trigger] self.user.contains_key(v) ==> {
196.                 &&& is_page_aligned(self.user[v].frame)
197.                 &&& spec_is_physical_region(self.user[v].frame, page_size())
198.                 &&& (self.user[v].cow ==> !self.user[v].perms.write)
199.             }
200.         // Kernel frames are valid and page-aligned.
201.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v) ==> {
202.                 &&& is_page_aligned(self.kernel[v].frame)
203.                 &&& spec_is_physical_region(self.kernel[v].frame, page_size())
204.             }
205.         // The page directory has a valid, page-aligned physical base.
206.         &&& is_page_aligned(self.pgdir)
207.         &&& spec_is_physical_region(self.pgdir, page_size())
208.     }
209. 
210.     //==============================================================================================
211.     // Observers
212.     //==============================================================================================
213. 
214.     /// Whether user virtual page `v` is mapped.
215.     pub open spec fn user_mapped(self, v: nat) -> bool {
216.         self.user.contains_key(v)
217.     }
218. 
219.     /// Whether kernel virtual page `v` is mapped.
220.     pub open spec fn kernel_mapped(self, v: nat) -> bool {
221.         self.kernel.contains_key(v)
222.     }
223. 
224.     /// Every CoW user page overlapping `[start, start+size)` is privatized.
225.     pub open spec fn region_cow_resolved(self, start: nat, size: nat) -> bool {
226.         forall|v: nat| #[trigger] self.user.contains_key(v)
227.             && page_base(start) <= v < start + size
228.             ==> !self.user[v].cow
229.     }
230. 
231.     //==============================================================================================
232.     // State transitions (mutators preserve unchanged fields via `..self`)
233.     //==============================================================================================
234. 
235.     pub open spec fn spec_map(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
236.         VmemView { user: self.user.insert(v, UserPageView { frame, perms, cow: false }), ..self }
237.     }
238. 
239.     pub open spec fn spec_unmap(self, v: nat) -> VmemView {
240.         VmemView { user: self.user.remove(v), ..self }
241.     }
242. 
243.     pub open spec fn spec_map_kpage(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
244.         VmemView { kernel: self.kernel.insert(v, KernelPageView { frame, perms }), ..self }
245.     }
246. 
247.     pub open spec fn spec_mark_cow(self, v: nat) -> VmemView {
248.         VmemView {
249.             user: self.user.insert(
250.                 v,
251.                 UserPageView {
252.                     perms: PagePerms { write: false, ..self.user[v].perms },
253.                     cow: true,
254.                     ..self.user[v]
255.                 },
256.             ),
257.             ..self
258.         }
259.     }
260. 
261.     pub open spec fn spec_unmark_cow(self, v: nat) -> VmemView {
262.         VmemView {
263.             user: self.user.insert(
264.                 v,
265.                 UserPageView {
266.                     perms: PagePerms { write: true, ..self.user[v].perms },
267.                     cow: false,
268.                     ..self.user[v]
269.                 },
270.             ),
271.             ..self
272.         }
273.     }
274. 
275.     /// `new_frame` is the freshly allocated private frame supplied existentially
276.     /// by the caller's ensures clause.
277.     pub open spec fn spec_resolve_cow(self, v: nat, new_frame: nat) -> VmemView {
278.         VmemView {
279.             user: self.user.insert(
280.                 v,
281.                 UserPageView {
282.                     frame: new_frame,
283.                     perms: PagePerms { write: true, ..self.user[v].perms },
284.                     cow: false,
285.                 },
286.             ),
287.             ..self
288.         }
289.     }
290. 
291.     pub open spec fn spec_uctrl(self, v: nat, perms: PagePerms) -> VmemView {
292.         VmemView {
293.             user: self.user.insert(v, UserPageView { perms, ..self.user[v] }),
294.             ..self
295.         }
296.     }
297. 
298.     pub open spec fn spec_kctrl(self, v: nat, perms: PagePerms) -> VmemView {
299.         VmemView {
300.             kernel: self.kernel.insert(v, KernelPageView { perms, ..self.kernel[v] }),
301.             ..self
302.         }
303.     }
304. }
305. 
306. //==================================================================================================
307. // Vmem — View and invariant
308. //==================================================================================================
309. 
310. impl View for Vmem {
311.     type V = VmemView;
312. 
313.     closed spec fn view(&self) -> VmemView {
314.         self.vmem_view@
315.     }
316. }
317. 
318. impl Vmem {
319.     /// Top-level invariant: the abstract view is well-formed.
320.     pub open spec fn inv(&self) -> bool {
321.         &&& self@.inv()
322.         &&& self.internal_inv()
323.     }
324. 
325.     /// Internal consistency between the concrete page-table representation and
326.     /// the abstract view. Refined during the proving phase.
327.     pub open spec fn internal_inv(&self) -> bool {
328.         true
329.     }
330. }
331. 
332. } // verus!
