124.     pub fn new(
125.         mut kernel_pages: LinkedList<KernelPage>,
126.         mut kernel_page_tables: LinkedList<(PageTableAddress, PageTable<PageTableStorage>)>,
127.     ) -> Result<Self, Error> {
128.         trace!("kernel_pages.len()={}", kernel_pages.len());
129. 
130.         // Create a clean page directory.
131.         let mut pgdir: PageDirectory<PageDirectoryStorage> =
132.             // SAFETY: this constructor is only used during early single-threaded init;
133.             // BSS is zero-initialized, so assume_init_mut() is sound for integer arrays.
134.             PageDirectory::new(PageDirectoryStorage::Bss(unsafe {
135.                 PAGE_TABLE_ALLOCATOR
136.                     .alloc_as::<[PteWord; PAGE_TABLE_LENGTH]>()
137.                     .map_err(|e| {
138.                         error!("Vmem::new(): page directory allocation failed: {}", e);
139.                         Error::new(ErrorCode::OutOfMemory, "BSS page directory allocation failed")
140.                     })?
141.                     .assume_init_mut()
142.             }));
143. 
144.         // Map and store root page tables.
145.         let mut kpage_tables: LinkedList<
146.             Rc<RefCell<(PageTableAddress, PageTable<PageTableStorage>)>>,
147.         > = LinkedList::new();
148.         while let Some((vaddr, page_table)) = kernel_page_tables.pop_front() {
149.             let page_table_address: FrameAddress = page_table.physical_address()?;
150.             // FIXME: do not be so open about permissions.
151.             pgdir.map(vaddr, page_table_address, false, AccessPermission::RDWR)?;
152.             kpage_tables.push_back(Rc::new(RefCell::new((vaddr, page_table))));
153.         }
154. 
155.         // Register the kernel page directory for lazy identity mapping and set CR3.
156.         {
157.             use crate::hal::mem::PageDirectoryAddress;
158.             use ::arch::cpu::cr3::{
159.                 Cr3Register,
160.                 PageDirectoryBaseAddress as Cr3PageDirectoryBaseAddress,
161.                 PageLevelCacheDisableFlag,
162.                 PageLevelWriteThroughFlag,
163.             };
164.             let pd_paddr_raw: usize = pgdir.physical_address()?.into_raw_value();
165.             let pd_paddr: PageDirectoryAddress =
166.                 PageDirectoryAddress::from_raw_value(pd_paddr_raw)?;
167.             let kernel_cr3: Cr3Register = Cr3Register {
168.                 page_level_write_through: PageLevelWriteThroughFlag::Disabled,
169.                 page_level_cache_disable: PageLevelCacheDisableFlag::Enabled,
170.                 paging_structure_base_address: Cr3PageDirectoryBaseAddress::new(
171.                     pd_paddr_raw as u32,
172.                 )
173.                 .ok_or_else(|| {
174.                     Error::new(
175.                         ErrorCode::BadAddress,
176.                         "kernel page directory address is not 4 KB aligned",
177.                     )
178.                 })?,
179.             };
180.             super::identity_map_init(pd_paddr, kernel_cr3)?;
181.         }
182. 
183.         // Store root pages.
184.         let mut kpages: LinkedList<Rc<RefCell<KernelPage>>> = LinkedList::new();
185.         while let Some(entry) = kernel_pages.pop_front() {
186.             kpages.push_back(Rc::new(RefCell::new(entry)));
187.         }
