212.     pub fn clone(from: &Vmem, pgdir_page: KernelPage) -> Result<Vmem, Error> {
213.         // Create a clean page directory backed by a kernel page from the pool.
214.         let mut pgdir: PageDirectory<PageDirectoryStorage> =
215.             PageDirectory::new(PageDirectoryStorage::KernelPage(pgdir_page));
216. 
217.         // Map and store root page tables.
218.         let mut kernel_page_tables: LinkedList<
219.             Rc<RefCell<(PageTableAddress, PageTable<PageTableStorage>)>>,
220.         > = LinkedList::new();
221.         let mut kernel_page_table_iter = from.kernel_page_tables.iter();
222.         loop {
223.             let entry = match kernel_page_table_iter.next() {
224.                 Some(entry) => entry,
