275.     ///
276.     /// # Description
277.     ///
278.     /// Maps a kernel page to the target virtual address space.
279.     ///
280.     /// # Parameters
281.     /// - `kpage`: Kernel page to be mapped.
282.     /// - `vaddr`: Virtual address of the target page.
283.     ///
284.     /// # Returns
285.     ///
286.     /// Upon success, empty is returned. Upon failure, an error code is returned instead.
287.     ///
288.     pub fn map_kpage(
289.         &mut self,
290.         kpage: KernelPage,
291.         vaddr: PageAligned<VirtualAddress>,
292.     ) -> Result<(), Error> {
293.         let pt_vaddr: PageTableAddress = PageTableAddress::new(PageTableAligned::from_raw_value(
294.             ::sys::mm::align_down(vaddr.into_raw_value(), PGTAB_ALIGNMENT),
295.         )?);
296. 
297.         // Get the corresponding page directory entry.
298.         let pde: PageDirectoryEntry = match self.pgdir.read_pde(pt_vaddr) {
299.             Some(pde) => pde,
300.             None => {
301.                 let reason: &str = "failed to read page directory entry";
302.                 error!("{reason}");
303.                 return Err(Error::new(ErrorCode::TryAgain, reason));
304.             },
305.         };
306. 
307.         // Check if page table does not exist.
308.         if !pde.is_present() {
309.             let page_table: PageTable<PageTableStorage> = Self::allocate_kernel_page_table()?;
310. 
311.             // FIXME: do not be so open about permissions.
312.             self.pgdir.map(
313.                 pt_vaddr,
314.                 page_table.physical_address()?,
315.                 false,
316.                 AccessPermission::RDWR,
317.             )?;
318. 
319.             //===================================================================
320.             // NOTE: if we fail beyond this point we should unmap the page table.
321.             //===================================================================
322. 
323.             // Add page table to the list of kernel page tables.
324.             self.kernel_page_tables
325.                 .push_back(Rc::new(RefCell::new((pt_vaddr, page_table))));
326.         };
327. 
328.         // Get corresponding page table.
329.         let mut kernel_page_table_iter = self.kernel_page_tables.iter_mut();
330.         loop {
331.             let entry = match kernel_page_table_iter.next() {
332.                 Some(entry) => entry,
333.                 None => break,
334.             };
335.             if entry.borrow().0.into_raw_value() == pt_vaddr.into_raw_value() {
336.                 // Map the page to the target virtual address space.
337.                 // FIXME: do not be so open about permissions and caching.
338.                 entry.borrow_mut().1.map(
339.                     PageAddress::new(vaddr),
340.                     kpage.frame_address(),
341.                     true,
342.                     true,
343.                     false,
344.                     AccessPermission::RDWR,
345.                 )?;
346. 
347.                 // Add the kernel page to the list of kernel pages.
348.                 self.kernel_pages.push_back(Rc::new(RefCell::new(kpage)));
349. 
350.                 // Reload page directory to force a TLB flush.
351.                 self.load()?;
352. 
353.                 return Ok(());
354.             }
355.         }
356. 
357.         let reason: &str = "page table not found";
358.         error!("{reason}");
359.         Err(Error::new(ErrorCode::NoSuchEntry, reason))
360.     }
