370.     ///
371.     #[cfg_attr(verus_keep_ghost, verus_verify(external_body))]
372.     fn allocate_kernel_page_table() -> Result<PageTable<PageTableStorage>, Error> {
373.         let kpage: KernelPage = {
374.             // SAFETY: the memory manager is initialized and access is synchronized.
375.             let mm: &mut VirtMemoryManager = unsafe { VirtMemoryManager::get_mut() };
376.             mm.alloc_kpage(true)?
377.         };
378.         let pgtable_storage: PageTableStorage = PageTableStorage::KernelPage(kpage);
379.         let page_table: PageTable<PageTableStorage> = PageTable::new(pgtable_storage);
380.         Ok(page_table)
381.     }
