385.     ///
386.     /// Allocate a page table for mapping user memory.
387.     ///
388.     /// # Returns
389.     ///
390.     /// Upon success, `Ok(page_table)` is returned. Upon failure, an error is returned.
391.     ///
392.     #[cfg_attr(verus_keep_ghost, verus_verify(external_body))]
393.     fn allocate_user_page_table() -> Result<PageTable<PageTableStorage>, Error> {
394.         // SAFETY: the kernel is single-threaded and runs with interrupts disabled; no
395.         // concurrent or re-entrant access to the physical memory manager is possible.
396.         let mut kframe: KernelFrame =
397.             unsafe { PhysMemoryManager::get_mut() }.alloc_kernel_frame()?;
398.         kframe.clear()?;
399.         let kpage: KernelPage = KernelPage::new(kframe);
400.         let pgtable_storage: PageTableStorage = PageTableStorage::KernelPage(kpage);
401.         let page_table: PageTable<PageTableStorage> = PageTable::new(pgtable_storage);
402.         Ok(page_table)
403.     }
